      pt: ["Construída no ano 1930.", "Desenhada por Paul Tournon.", "Sem função religiosa desde 1956."],
      fr: ["Construite en 1930.", "Conçue par Paul Tournon.", "N'a plus de fonction religieuse depuis 1956."],
