      en: ["Founded: 12th century (Almohad dynasty)", "Location: Kasbah district of the Marrakech Medina", "Current role: Official residence of the King of Morocco", "Accessibility: Not open to the general public", "Architecture: Fortified complex with high clay walls", "Significance: Center of royal authority in Marrakech"],
      es: ["Los orígenes se remontan al siglo XII (dinastía almohade).", "El palacio actual fue construido principalmente por los alauíes.", "El complejo está totalmente rodeado por altos muros.", "El acceso al público está estrictamente prohibido.", "La entrada principal se encuentra en la plaza del Mechouar.", "Adyacentes al palacio se encuentran los históricos Jardines del Agdal.", "El palacio es un laberinto de patios, pabellones y jardines.", "Es una de las varias residencias oficiales del rey marroquí en el país."],
