      fr: ["Les origines remontent au XIIe siècle (dynastie Almohade).", "Le palais actuel a été principalement construit par les Alaouites.", "Le complexe est entièrement entouré de hauts murs.", "L'accès au public est strictement interdit.", "L'entrée principale se trouve sur la place du Mechouar.", "Les jardins historiques de l'Agdal sont adjacents au palais.", "Le palais est un labyrinthe de cours, de pavillons et de jardins.", "Il s'agit de l'une des nombreuses résidences officielles du roi du Maroc dans le pays."],
