    image: "/poi-images/ma-marrakech-dar-si-said-landmarks-v2.webp",
    description: {
      de: "Dar Si Said ist ein prächtiger Palast aus dem späten 19. Jahrhundert in Marrakesch, der heute das Museum für marokkanische Holzkunst beherbergt. Seine aufwendige andalusisch-marokkanische Architektur und die friedlichen Innenhöfe machen ihn zu einem herausragenden Denkmal.",
      hu: "A Dar Si Said egy 19. század végi lenyűgöző palota Marrákesben, amely ma a marokkói faművészet múzeumának ad otthont. Kidolgozott andalúz-marokkói építészete és békés belső udvarai kiemelkedő műemlékké teszik.",
      ro: "Dar Si Said este un palat magnific de la sfârșitul secolului al XIX-lea din Marrakech, care găzduiește astăzi muzeul de artă a lemnului marocan. Arhitectura sa andaluz-marocană elaborată și curțile pașnice îl fac un monument remarcabil.",
      en: "Dar Si Said is a magnificent late 19th-century palace in Marrakech that now houses the museum of Moroccan woodwork. Its elaborate Andalusian-Moroccan architecture and peaceful courtyards make it an outstanding monument.",
      es: "Dar Si Said es un magnífico palacio de finales del siglo XIX en Marrakech, que hoy alberga el Museo de las Artes de la Madera Marroquíes. Su elaborada arquitectura andaluza-marroquí y sus tranquilos patios interiores lo convierten en un monumento excepcional.",
      pt: "Dar Si Said é um magnífico palácio do final do século XIX em Marraquexe, que hoje alberga o Museu de Arte em Madeira Marroquina. A sua elaborada arquitetura andaluza-marroquina e os seus pátios interiores tranquilos tornam-no num monumento de destaque.",
      fr: "Dar Si Saïd est un magnifique palais de la fin du XIXe siècle à Marrakech, qui abrite aujourd'hui le musée de l'art du bois marocain. Son architecture andalou-marocaine complexe et ses cours intérieures paisibles en font un monument exceptionnel.",
    },
