      es: ["Construido por el hermano del gran visir Ba Ahmed.", "Muestra una rica colección de alfombras tradicionales.", "Famoso por su detallada bóveda de techo de madera de cedro."],
      pt: ["Construído pelo irmão do Grão-Vizir Ba Ahmed.", "Exibe uma rica coleção de tapetes tradicionais.", "Famoso pelo seu teto de madeira de cedro ricamente detalhado."],
