      ro: ["Data construcției: Secolul al XVII-lea", "Localizare: Cartierul Mellah din Fez", "Restaurare: Finalizată în anul 1999", "Dotare: Include o mikva (baie rituală)", "Arhitectură: Pardoseală din plăci alb-albastre", "Importanță: Monument al patrimoniului evreiesc"],
      en: ["Built: 17th century", "Location: Mellah district (Jewish Quarter) of Fez", "Reopening: 1999 following restoration", "Key feature: Houses a natural ritual mikvah", "Interior: Traditional blue-and-white tiling", "Significance: Leading Jewish landmark in North Africa"],
      es: ["Construida en el siglo XVII por la familia Ibn Danan.", "Una de las sinagogas más antiguas que existen en Fez.", "Restaurada en los años 90 con ayuda del World Monuments Fund.", "Alberga una colección de objetos históricos judíos.", "El arca de la Torá está hecha de madera artísticamente tallada.", "Muestra la construcción típica de las sinagogas sefardíes en el norte de África.", "Forma parte del Patrimonio de la Humanidad de la UNESCO de la Medina de Fez.", "Simboliza la convivencia histórica de judíos y musulmanes en Marruecos."],
      pt: ["Construída no século XVII pela família Ibn Danan.", "Uma das sinagogas mais antigas ainda existentes em Fès.", "Foi restaurada na década de 1990 com a ajuda do World Monuments Fund.", "Abriga uma coleção de objetos históricos judaicos.", "O santuário da Torá é feito de madeira artisticamente entalhada.", "Mostra o estilo de construção típico das sinagogas sefarditas no Norte de África.", "Faz parte do Património Mundial da UNESCO da Medina de Fès.", "Simboliza a coexistência histórica de judeus e muçulmanos em Marrocos."],
      fr: ["Construite au XVIIe siècle par la famille Ibn Danan.", "L'une des plus anciennes synagogues encore existantes à Fès.", "Restaurée dans les années 1990 avec l'aide du World Monuments Fund.", "Abrite une collection d'objets juifs historiques.", "L'arche sainte est faite de bois sculpté avec art.", "Illustre l'architecture typique des synagogues séfarades en Afrique du Nord.", "Fait partie du patrimoine mondial de l'UNESCO de la médina de Fès.", "Symbolise la coexistence historique entre juifs et musulmans au Maroc."],
