      es: ["Construida en 1321 bajo el mandato del sultán Abu al-Hasan.", "'Sahrij' significa 'estanque' en árabe.", "Recientemente restaurada de forma integral."],
      pt: ["Construída em 1321 sob o sultão Abu al-Hasan.", "'Sahrij' significa 'tanque' em árabe.", "Foi recentemente restaurada de forma abrangente."],
