      hu: ["1919 és 1921 között épült", "Adrien Laforgue építész tervezte", "A tornyokat 1930-ban adták hozzá", "A Rabati Főegyházmegye székhelye", "Stílusa Art Deco", "A Place du Golan téren található"],
      ro: ["Construită între 1919 și 1921", "Proiectată de arhitectul Adrien Laforgue", "Turnurile au fost adăugate în 1930", "Sediul Arhidiecezei de Rabat", "Stil arhitectural Art Deco", "Situată în Place du Golan"],
