      es: ["Colocación de la primera piedra en 1919.", "Diseñada por el arquitecto francés Adrien Laforgue.", "Las dos torres no se terminaron hasta 1930.", "Es la sede oficial del arzobispo de Rabat.", "Ejemplo del estilo Art Déco popular en las décadas de 1920 y 1930.", "Una de las pocas catedrales activas en Marruecos.", "El Papa Francisco visitó la catedral durante su viaje a Marruecos en 2019.", "La sencilla decoración interior dirige la mirada hacia el altar."],
      pt: ["Lançamento da primeira pedra em 1919.", "Projetada pelo arquiteto francês Adrien Laforgue.", "As duas torres só foram concluídas em 1930.", "É a sede oficial do arcebispo de Rabat.", "Exemplo do estilo Art Déco, popular nas décadas de 1920 e 1930.", "Uma das poucas catedrais ativas em Marrocos.", "O Papa Francisco visitou a catedral durante a sua viagem a Marrocos em 2019.", "A decoração interior simples direciona o olhar para o altar."],
      fr: ["Pose de la première pierre en 1919.", "Conçue par l'architecte français Adrien Laforgue.", "Les deux tours n'ont été achevées qu'en 1930.", "C'est le siège officiel de l'archevêque de Rabat.", "Un exemple du style Art déco populaire dans les années 1920 et 1930.", "L'une des rares cathédrales encore actives au Maroc.", "Le pape François a visité la cathédrale lors de son voyage au Maroc en 2019.", "L'aménagement intérieur sobre attire le regard vers l'autel."],
