      hu: ["1142 körül alapították az Almohádok", "1292-ben a Merinidák bővítették ki", "Csillárja 514 olajlámpát tartalmaz", "A csillár súlya körülbelül 3 tonna", "Almohád és merinida stílusú építészet", "Taza medinájának legfontosabb műemléke"],
      ro: ["Fondată în jurul anului 1142 de Almohazii", "Extinsă în anul 1292 de către Merinizi", "Deține un candelabru cu 514 lămpi cu ulei", "Candelabrul cântărește aproximativ 3 tone", "Arhitectură în stil Almohad și Merinid", "Cel mai important monument din medina Tazei"],
      en: ["Founded around 1142 by the Almohads", "Expanded in 1292 by the Merinids", "Features a chandelier with 514 oil lamps", "The chandelier weighs about 3 tons", "Almohad and Merinid architectural styles", "Most important monument in Taza's medina"],
      es: ["Fundada hacia 1142 por los almohades.", "Ampliada a finales del siglo XIII por los benimerines.", "Famosa por su cúpula artísticamente calada.", "La gran lámpara de bronce fue donada en 1294 por el sultán Abu Yaqub Yusuf.", "La lámpara tiene más de 500 cuencos para lámparas de aceite.", "La mezquita es un ejemplo poco común de mezquita almohade conservada.", "Se encuentra en la antigua medina de Taza.", "Su arquitectura influyó en construcciones posteriores en Marruecos y Andalucía."],
      pt: ["Fundada por volta de 1142 pelos almóadas.", "Ampliada no final do século XIII pelos merínidas.", "Famosa pela sua cúpula artisticamente rendilhada.", "O grande lustre de bronze foi doado em 1294 pelo Sultão Abu Yaqub Yusuf.", "O lustre possui mais de 500 taças para lâmpadas de óleo.", "A mesquita é um exemplo raro de uma mesquita almóada preservada.", "Localiza-se na antiga medina de Taza.", "A arquitetura influenciou construções posteriores em Marrocos e na Andaluzia."],
      fr: ["Fondée vers 1142 par les Almohades.", "Agrandie à la fin du XIIIe siècle par les Mérinides.", "Célèbre pour sa coupole aux sculptures ajourées.", "Le grand lustre en bronze fut offert en 1294 par le sultan Abu Yaqub Yusuf.", "Le lustre compte plus de 500 godets pour lampes à huile.", "La mosquée est un rare exemple de mosquée almohade préservée.", "Elle se situe dans la vieille médina de Taza.", "Son architecture a influencé les constructions ultérieures au Maroc et en Andalousie."],
