      hu: ["1582-ben épült Ahmad al-Mansur alatt", "A Borj Nord északi erőd párja", "Portugál katonai építészet hatása látszik rajta", "360 fokos kilátást nyújt Fes el-Balira", "A város ellenőrzésére használták", "Masszív vályogfalakból és bástyákból áll"],
      ro: ["Construit în anul 1582 sub Ahmad al-Mansur", "Omologul fortăreței nordice Borj Nord", "Arhitectură influențată de designul portughez", "Oferă o vedere de 360 de grade asupra Fes el-Bali", "Folosit pentru a supraveghea orașul", "Construit din ziduri masive de pământ și bastioane"],
