      es: ["Construida hacia 1582 por el sultán Ahmad al-Mansur.", "Forma pareja con el Borj Nord en el lado norte de la ciudad.", "La arquitectura muestra influencias de las fortificaciones portuguesas.", "El propósito principal era el control militar de la ciudad de Fez.", "Ofrece la mejor vista panorámica de la Medina.", "Construida con piedra maciza y adobe.", "La fortaleza es muy popular entre los fotógrafos.", "Cerca se encuentran los antiguos cementerios judío y cristiano."],
      pt: ["Construída por volta de 1582 pelo sultão Ahmad al-Mansur.", "Forma o par com o Borj Nord no lado norte da cidade.", "A arquitetura mostra influências de fortificações portuguesas.", "O objetivo principal era o controlo militar da cidade de Fès.", "Oferece a melhor vista panorâmica da Medina.", "Construída em pedra maciça e argila.", "A fortaleza é particularmente popular entre fotógrafos.", "Nas proximidades encontram-se os antigos cemitérios judeus e cristãos."],
      fr: ["Construite vers 1582 par le sultan Ahmed al-Mansour.", "Forme le pendant du Borj Nord situé au nord de la ville.", "L'architecture présente des influences de fortifications portugaises.", "L'objectif principal était le contrôle militaire de la ville de Fès.", "Offre le meilleur panorama sur la médina.", "Bâtie en pierre massive et en pisé.", "La forteresse est particulièrement prisée des photographes.", "Les anciens cimetières juif et chrétien se trouvent à proximité."],
