      ro: ["Construită în anii 1920", "Edificată de autoritățile coloniale spaniole", "Nu a fost niciodată folosită ca moschee", "Oferă cea mai bună vedere asupra Chefchaouen", "Restaurată în secolul XXI", "Situată la cca. 15 minute de mers de medină"],
      en: ["Built in the 1920s", "Constructed by Spanish colonial authorities", "Never actually used for religious worship", "Provides the best panoramic view of Chefchaouen", "Restored during the 21st century", "Located about a 15-minute walk from the medina"],
      es: ["Construida en los años 20 durante el protectorado español.", "Nunca fue aceptada por los lugareños como lugar de oración.", "Situada en una colina frente a la Medina de Chefchaouen.", "El camino hacia la mezquita bordea el río Ras El Maa.", "Uno de los lugares favoritos para fotografiar el atardecer.", "El edificio es sencillo y sin adornos.", "La vista abarca toda la medina azul y las montañas del Rif.", "El nombre 'Jemaa Bouzafar' hace referencia al antiguo nombre del lugar."],
      pt: ["Construída na década de 1920 durante o protetorado espanhol.", "Nunca foi aceite pelos locais como casa de oração.", "Situada numa colina em frente à Medina de Chefchaouen.", "O caminho para a mesquita segue ao longo do rio Ras El Maa.", "Um dos locais favoritos para fotografar o pôr do sol.", "O edifício em si é simples e sem adornos.", "A vista abrange toda a medina azul e as montanhas de Rif circundantes.", "O nome 'Jemaa Bouzafar' refere-se ao antigo nome do local."],
      fr: ["Construite dans les années 1920 pendant le protectorat espagnol.", "Ne fut jamais acceptée par les locaux comme lieu de culte.", "Située sur une colline face à la médina de Chefchaouen.", "Le chemin vers la mosquée longe la rivière Ras El Maa.", "L'un des endroits les plus populaires pour photographier le coucher du soleil.", "Le bâtiment lui-même est simple et sans fioritures.", "La vue embrasse toute la médina bleue et les montagnes du Rif environnantes.", "Le nom 'Jemaa Bouzafar' fait référence à l'ancien nom du lieu."],
