      ro: ["Construită în secolul al XVIII-lea", "Parte a zidurilor de apărare din Essaouira", "A servit drept depozit de praf de pușcă", "Poarta principală pentru comerțul cu Marrakech", "Găzduiește în prezent galerii de artă", "Construcție masivă din piatră locală"],
