      es: ["Parte de las fortificaciones construidas en el siglo XVIII.", "Históricamente conducía a la ruta comercial hacia Marrakech.", "La forma redonda del bastión es inusual para las puertas marroquíes.", "La arquitectura fue influenciada por el ingeniero francés Théodore Cornut.", "Hoy en día hay un animado mercado local cerca.", "El bastión se utiliza ocasionalmente como espacio de arte.", "La puerta es un buen ejemplo de la arquitectura militar del siglo XVIII en Marruecos.", "Es una de las puertas principales que dan acceso a la Medina protegida por la UNESCO."],
      pt: ["Parte das fortificações da cidade construídas no século XVIII.", "Historicamente levava à rota comercial para Marraquexe.", "A forma circular do bastião é invulgar para as portas marroquinas.", "A arquitetura foi influenciada pelo engenheiro francês Théodore Cornut.", "Hoje existe um mercado local vibrante nas proximidades.", "O bastião é ocasionalmente utilizado como espaço de arte.", "A porta é um bom exemplo da arquitetura militar do século XVIII em Marrocos.", "É uma das portas principais que dão acesso à Medina protegida pela UNESCO."],
      fr: ["Fait partie des fortifications de la ville construites au XVIIIe siècle.", "Menait historiquement à la route commerciale vers Marrakech.", "La forme ronde du bastion est inhabituelle pour les portes marocaines.", "L'architecture a été influencée par l'ingénieur français Théodore Cornut.", "Un marché local animé se trouve aujourd'hui à proximité.", "Le bastion est occasionnellement utilisé comme espace artistique.", "La porte est un bel exemple d'architecture militaire du XVIIIe siècle au Maroc.", "C'est l'une des portes principales menant à la médina protégée par l'UNESCO."],
